python3 -c "
import json, glob
for f in sorted(glob.glob('/root/ratekv/mistral*.json')):
    try:
        data = json.load(open(f))
        hits = {k: v for k, v in data.items() if 'concentration' in k.lower() or 'top5' in k.lower() or 'top_5' in k.lower()}
        print(f'{f}:')
        if hits:
            for k, v in hits.items():
                print(f'  {k} = {v}')
        else:
            print('  (no concentration key)')
    except Exception as e:
        print(f'{f}: ERROR {e}')
"
